import React from 'react';

interface ProgressRingProps {
  radius: number;
  stroke: number;
  progress: number;
  label: string;
}

const ProgressRing: React.FC<ProgressRingProps> = ({ radius, stroke, progress, label }) => {
  const normalizedRadius = radius - stroke * 2;
  const circumference = normalizedRadius * 2 * Math.PI;
  const strokeDashoffset = circumference - (progress / 100) * circumference;

  return (
    <div className="flex flex-col items-center justify-center p-6 transform-gpu">
      <div className="relative flex items-center justify-center">
        <svg
          height={radius * 2}
          width={radius * 2}
          className="transform-gpu"
        >
          {/* Background circle */}
          <circle
            stroke="rgba(255, 255, 255, 0.05)"
            fill="transparent"
            strokeWidth={stroke}
            r={normalizedRadius}
            cx={radius}
            cy={radius}
          />
          {/* Progress circle */}
          <circle
            stroke="#10b981"
            fill="transparent"
            strokeWidth={stroke}
            strokeDasharray={circumference + ' ' + circumference}
            style={{ strokeDashoffset }}
            strokeLinecap="round"
            className="progress-ring__circle"
            r={normalizedRadius}
            cx={radius}
            cy={radius}
          />
        </svg>
        <div className="absolute inset-0 flex flex-col items-center justify-center">
          <span className="text-3xl font-bold text-white leading-none">{Math.round(progress)}%</span>
          <span className="text-[10px] uppercase tracking-wider text-emerald-500 font-semibold mt-1">Ihsan Score</span>
        </div>
      </div>
      <p className="mt-4 text-slate-400 text-sm font-medium">{label}</p>
    </div>
  );
};

export default ProgressRing;

