import React, { useState, useEffect, useMemo } from 'react';
import { Language, ProgressState, DayRecord } from '../types';
import { ROUTINE_ITEMS, TRANSLATIONS } from '../constants';
import ProgressRing from './ProgressRing';
import CheckItem from './CheckItem';

const STORAGE_KEY = 'ihsan-routine-hub-progress';
const DATE_KEY = 'ihsan-routine-hub-date';
const HISTORY_KEY = 'ihsan-routine-hub-history';

const RoutineCheck: React.FC = () => {
  const [lang, setLang] = useState<Language>('en');
  const [progress, setProgress] = useState<ProgressState>({});
  const isRtl = lang === 'ur' || lang === 'ar';

  // Initialize state and history tracking
  useEffect(() => {
    const today = new Date().toISOString().split('T')[0];
    const savedDate = localStorage.getItem(DATE_KEY);

    if (savedDate && savedDate !== today) {
      // Save previous progress to history
      const prevProgress = JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}');
      const history: DayRecord[] = JSON.parse(localStorage.getItem(HISTORY_KEY) || '[]');

      const isFridayPrev = new Date(savedDate).getDay() === 5;
      const relevantItems = ROUTINE_ITEMS.filter(item => 
        item.variant === 'virtue' && (!item.isFridayOnly || (item.isFridayOnly && isFridayPrev))
      );
      const completed = relevantItems.filter(item => prevProgress[item.id]).length;
      const prevScore = (completed / relevantItems.length) * 100;

      history.push({ date: savedDate, progress: prevProgress, score: prevScore });

      // Limit history to last 60 days to keep localStorage clean
      const trimmedHistory = history.slice(-60);
      localStorage.setItem(HISTORY_KEY, JSON.stringify(trimmedHistory));

      // Reset for new day
      localStorage.setItem(DATE_KEY, today);
      localStorage.setItem(STORAGE_KEY, JSON.stringify({}));
      setProgress({});
    } else if (!savedDate) {
      localStorage.setItem(DATE_KEY, today);
    } else {
      const savedProgress = localStorage.getItem(STORAGE_KEY);
      if (savedProgress) {
        setProgress(JSON.parse(savedProgress));
      }
    }
  }, []);

  // Save to local storage on change
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(progress));
  }, [progress]);

  const toggleItem = (id: string) => {
    setProgress(prev => ({
      ...prev,
      [id]: !prev[id]
    }));
  };

  const isFriday = new Date().getDay() === 5;
  const filteredItems = useMemo(() => {
    return ROUTINE_ITEMS.filter(item => !item.isFridayOnly || (item.isFridayOnly && isFriday));
  }, [isFriday]);

  const progressPercentage = useMemo(() => {
    const virtueItems = filteredItems.filter(item => item.variant === 'virtue');
    const total = virtueItems.length;
    const completed = virtueItems.filter(item => progress[item.id]).length;
    return total === 0 ? 0 : (completed / total) * 100;
  }, [filteredItems, progress]);

  const t = TRANSLATIONS[lang];

  const downloadData = (type: 'daily' | 'weekly' | 'monthly') => {
    const today = new Date().toISOString().split('T')[0];
    const history: DayRecord[] = JSON.parse(localStorage.getItem(HISTORY_KEY) || '[]');
    let dataToExport: any = [];

    if (type === 'daily') {
      dataToExport = [{ date: today, progress, score: progressPercentage }];
    } else if (type === 'weekly') {
      const last7Days = history.slice(-6);
      dataToExport = [...last7Days, { date: today, progress, score: progressPercentage }];
    } else if (type === 'monthly') {
      const last30Days = history.slice(-29);
      dataToExport = [...last30Days, { date: today, progress, score: progressPercentage }];
    }

    const blob = new Blob([JSON.stringify(dataToExport, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `Routine_Report_${type}_${today}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const renderSection = (category: string, title: string) => {
    const sectionItems = filteredItems.filter(item => item.category === category);
    if (sectionItems.length === 0) return null;

    return (
      <div className="mb-8 last:mb-0">
        <h3 className={`text-xs font-bold uppercase tracking-widest text-slate-500 mb-4 px-1 ${isRtl ? 'text-right' : 'text-left'}`}>
          {title}
        </h3>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-1 gap-2">
          {sectionItems.map(item => (
            <CheckItem
              key={item.id}
              id={item.id}
              label={t[item.labelKey as keyof typeof t]}
              checked={!!progress[item.id]}
              onChange={toggleItem}
              dir={isRtl ? 'rtl' : 'ltr'}
              variant={item.variant}
            />
          ))}
        </div>
      </div>
    );
  };

  const langNames: Record<Language, string> = {
    en: 'English',
    ur: 'اردو',
    hi: 'हिंदी',
    ar: 'العربية'
  };

  return (
    <div className={`max-w-md mx-auto p-6 md:p-8 min-h-screen pb-20`} dir={isRtl ? 'rtl' : 'ltr'}>
      {/* Language Switcher */}
      <div className="flex justify-center gap-1 mb-8 glass p-1 rounded-2xl transform-gpu overflow-x-auto">
        {(['en', 'ur', 'hi', 'ar'] as Language[]).map((l) => (
          <button
            key={l}
            onClick={() => setLang(l)}
            className={`
              flex-shrink-0 py-2 px-3 rounded-xl text-[10px] sm:text-xs font-semibold transition-all duration-200
              ${lang === l ? 'bg-emerald-500 text-white shadow-lg shadow-emerald-500/20' : 'text-slate-400 hover:text-white hover:bg-white/5'}
            `}
          >
            {langNames[l]}
          </button>
        ))}
      </div>

      {/* Progress Section */}
      <div className="glass rounded-[2rem] p-4 mb-8 overflow-hidden transform-gpu">
        <ProgressRing 
          radius={110} 
          stroke={10} 
          progress={progressPercentage} 
          label={t.score_label}
        />
      </div>

      {/* Content Sections */}
      <div className="space-y-4">
        {renderSection('salah_fardh', t.salah_fardh)}
        {renderSection('salah_nawafil', t.salah_nawafil)}
        {renderSection('tilawat', t.tilawat)}
        {renderSection('habits', t.habits)}
        {renderSection('avoidance', t.avoidance)}
      </div>

      {/* Report Download Area */}
      <div className="mt-12 p-6 glass rounded-2xl text-center space-y-4">
        <h4 className="text-xs font-bold uppercase tracking-widest text-emerald-500">{t.download_report}</h4>
        <div className="flex gap-2">
          <button onClick={() => downloadData('daily')} className="flex-1 py-2 rounded-xl bg-white/5 border border-white/10 hover:bg-white/10 text-xs font-medium transition-colors">
            {t.daily}
          </button>
          <button onClick={() => downloadData('weekly')} className="flex-1 py-2 rounded-xl bg-white/5 border border-white/10 hover:bg-white/10 text-xs font-medium transition-colors">
            {t.weekly}
          </button>
          <button onClick={() => downloadData('monthly')} className="flex-1 py-2 rounded-xl bg-white/5 border border-white/10 hover:bg-white/10 text-xs font-medium transition-colors">
            {t.monthly}
          </button>
        </div>
      </div>

      {/* Reset Logic */}
      <div className="mt-12 flex justify-center">
        <button 
          onClick={() => {
            if(confirm(t.reset_confirm)) {
              setProgress({});
            }
          }}
          className="text-xs text-slate-500 hover:text-red-400 transition-colors uppercase tracking-widest font-bold"
        >
          Reset Today's Progress
        </button>
      </div>
    </div>
  );
};

